			displayPath = "Sildihn criterion/Silkie",
			eventType = 13,
			execute = "local prior=_G.JacobSilkieGuide\nlocal now=GUI:GetTime()\nif prior and prior.lastPulse and now-prior.lastPulse<.25 then return end\n-- Owned helper state; no party-roster access or plugin settings are modified.\nlocal s=_G.JacobSilkieGuide\nif not s or s.version~=8 then\n s=s or {mode=1,phase=0,dead=false,draws={},tethers={}}\n s.version=8\n _G.JacobSilkieGuide=s\n s.registry=s.registry or {[11369]={},[11370]={},[11371]={}}\n s.raw=s.raw or {[11369]={},[11370]={},[11371]={}}\n function s.entities(cid)\n  local out,seen={},{}\n  for id in pairs(s.registry[cid] or {}) do\n   local e=TensorCore.mGetEntity(id)\n   if e then out[#out+1]=e;seen[id]=true end\n  end\n  for id in pairs(s.raw[cid] or {}) do\n   if not seen[id] then local e=TensorCore.mGetEntity(id);if e then out[#out+1]=e end end\n  end\n  return out\n end\n function s.plan1()\n  local green,remaining={},nil\n  local visible=0\n  for _,e in ipairs(s.entities(11370)) do\n   if (Argus.getEntityModel(e)==14835 or Argus.getEntityModel(e)==14838) and Argus.isEntityVisible(e) then\n    visible=visible+1\n    local _,_,kind=Argus.getEntityAuras(e)\n    if kind==1512 then green[#green+1]=e elseif kind==1510 or kind==1511 then remaining={entity=e,kind=kind} end\n   end\n  end\n  if visible~=3 or #green~=2 or not remaining then return nil end\n  local e=remaining.entity\n  local hazard={kind=remaining.kind==1510 and 'yellow' or 'cross',x=e.pos.x,z=e.pos.z,h=e.pos.h}\n  local threatened,other\n  for _,g in ipairs(green) do if not s.safe(g.pos,{hazard},0) then\n    if threatened then return nil end\n    threatened=g\n   else other=g end\n  end\n  if not threatened or not other then return nil end\n  return threatened,other\n end\n function s.clear()\n  for _,id in ipairs(s.draws) do Argus.deleteTimedShape(id) end\n  s.draws={};s.goal=nil;s.goalUntil=nil\n end\n function s.safe(p,hazards,margin)\n  margin=margin or .6\n  for _,a in ipairs(hazards) do\n   local dx,dz=p.x-a.x,p.z-a.z\n   local distance=math.sqrt(dx*dx+dz*dz)\n   local f=dx*math.sin(a.h or 0)+dz*math.cos(a.h or 0)\n   local r=dx*math.cos(a.h or 0)-dz*math.sin(a.h or 0)\n   if a.kind=='cross' and (math.abs(f)<=5+margin or math.abs(r)<=5+margin) then return false end\n   if a.kind=='donut' and distance>=5-margin and distance<=60+margin then return false end\n   if a.kind=='cone' and distance<=60+margin and (distance<=margin or f/distance>=math.cos(a.angle/2+math.asin(math.min(1,margin/distance)))) then return false end\n   if a.kind=='yellow' and distance<=60+margin then\n    for i=0,3 do\n     local h=(a.h or 0)+math.pi/4+i*math.pi/2\n     local dot=dx*math.sin(h)+dz*math.cos(h)\n     if distance<=margin or dot/distance>=math.cos(math.pi/8+math.asin(math.min(1,margin/distance))) then return false end\n    end\n   end\n   if a.kind=='water' and math.abs(dx)<=4+margin then return false end\n  end\n  return true\n end\n function s.hazards(predictPuffs)\n  local hazards={}\n  for _,cid in ipairs({11369,11370}) do\n   for _,e in pairs(s.entities(cid)) do\n    if e.pos then\n     local info=e.castinginfo\n     local id=info and info.channeltime<info.casttime-.05 and info.channelingid or 0\n     local a={x=e.pos.x,z=e.pos.z,h=e.pos.h}\n     if (id==30568 or id==30603) then a.kind='cross'\n     elseif (id==30569 or id==30604) then a.kind='donut'\n     elseif (id==30570 or id==30605) or (id==30557 or id==30592) or (id==30547 or id==30582) or (id==30548 or id==30583) then a.kind='cone';a.angle=math.pi/4\n     elseif (id==30549 or id==30584) or (id==30550 or id==30585) then a.kind='cone';a.angle=math.pi*1.25\n     elseif predictPuffs and cid==11370 and (Argus.getEntityModel(e)==14835 or Argus.getEntityModel(e)==14838) and Argus.isEntityVisible(e) then\n      local _,_,kind=Argus.getEntityAuras(e)\n      if kind==1510 then a.kind='yellow' elseif kind==1511 then a.kind='cross' elseif kind==1512 then a.kind='donut' end\n     end\n     if a.kind then hazards[#hazards+1]=a end\n    end\n   end\n  end\n  return hazards\n end\n function s.guide(point,ms,label,hazards,bait)\n  s.clear()\n  if not point or (not bait and not s.safe(point,hazards or s.hazards(true))) then return false end\n  local player=TensorCore.mGetPlayer()\n  if not player or not player.pos then return false end\n  local drawer=TensorCore.getStaticDrawer(0xFF66FF99,2)\n  local circle=drawer:addTimedCircle(ms,point.x,point.y+.05,point.z,.4,0,false,true,Argus2.RenderFlags.FLAG_RENDER_OVERLAY)\n  if circle then s.draws[#s.draws+1]=circle end\n  local distance=TensorCore.getDistance2d(player.pos,point)\n  if distance>1 then\n   local arrow=drawer:addTimedArrow(ms,player.pos.x,player.pos.y+.05,player.pos.z,TensorCore.getHeadingToTarget(player.pos,point),math.max(.1,distance-1),.8,1,1.4,0,false,Argus2.RenderFlags.FLAG_RENDER_OVERLAY)\n   if arrow then s.draws[#s.draws+1]=arrow end\n  end\n  s.goal=point;s.goalUntil=GUI:GetTime()+ms/1000;s.goalBait=bait\n  return true\n end\n function s.pick(candidates,hazards,reference)\n  local best,score=nil,math.huge\n  for _,p in ipairs(candidates) do\n   if s.safe(p,hazards) then\n    local d=TensorCore.getDistance2d(reference,p)\n    if d<score then best=p;score=d end\n   end\n  end\n  return best\n end\n function s.cardinal(boss,ms,label)\n  local player=TensorCore.mGetPlayer();if not player then return end\n  local job=player.job\n  local angle=math.pi/2\n  if job==19 or job==21 or job==32 or job==37 then angle=math.pi\n  elseif job==24 or job==28 or job==33 or job==40 then angle=0\n  elseif job==20 or job==22 or job==30 or job==34 or job==39 or job==41 then angle=-math.pi/2 end\n  local candidates={}\n  for _,radius in ipairs({10,9,8,11,12}) do\n   for _,offset in ipairs({0,-.1,.1,-.2,.2}) do\n    candidates[#candidates+1]={x=boss.pos.x+radius*math.sin(angle+offset),y=boss.pos.y,z=boss.pos.z+radius*math.cos(angle+offset)}\n   end\n  end\n  local hazards=s.hazards(true)\n  -- The yellow boss's four diagonal cones are part of the same resolution.\n  hazards[#hazards+1]={kind='yellow',x=boss.pos.x,z=boss.pos.z,h=boss.pos.h}\n  local preferred=candidates[1]\n  s.guide(s.pick(candidates,hazards,preferred),ms,label,hazards)\n end\nend\ns.lastPulse=GUI:GetTime()\ns.raw={[11369]={},[11370]={},[11371]={}}\nfor _,e in pairs(EntityList('') or {}) do\n if s.raw[e.contentid] then s.raw[e.contentid][e.id]=true end\nend\nlocal bosses=s.entities(11369)\nlocal boss\nfor _,e in pairs(bosses or {}) do\n if (Argus.getEntityModel(e)==14834 or Argus.getEntityModel(e)==14837) and e.pos then\n  if s.seenBossID==e.id and s.seenAlive and e.hp.current==0 then s.dead=true;s.clear() end\n  if Argus.isEntityVisible(e) and (not s.mainBossID or e.id==s.mainBossID) then boss=e;break end\n end\nend\ns.boss=boss\nif not boss then return end\ns.center={x=-335,y=boss.pos.y,z=-155} -- Cactbot and observed Silkie arena coordinates.\nif s.seenAlive and boss.hp.current==0 then s.dead=true;s.clear() end\nif boss.hp.current>0 then s.seenAlive=true;s.seenBossID=boss.id end\nif boss.incombat and not s.pullStart then s.pullStart=GUI:GetTime() end\nlocal puffs={};local blues=0;local sumX,sumZ=0,0\nfor _,e in pairs(s.entities(11370)) do\n if (Argus.getEntityModel(e)==14835 or Argus.getEntityModel(e)==14838) and e.pos and Argus.isEntityVisible(e) then\n  local _,_,kind=Argus.getEntityAuras(e)\n  puffs[#puffs+1]={entity=e,kind=kind};sumX=sumX+e.pos.x;sumZ=sumZ+e.pos.z\n  if kind==1511 then blues=blues+1 end\n end\nend\ns.puffs=puffs\nif #puffs==8 or #puffs==6 then\n s.phase=3\n local minZ,maxZ=math.huge,-math.huge\n for _,p in ipairs(puffs) do minZ=math.min(minZ,p.entity.pos.z);maxZ=math.max(maxZ,p.entity.pos.z) end\n s.rowMid=(minZ+maxZ)/2\nelseif #puffs==4 and blues==4 then\n s.phase=4\nelseif #puffs==3 then\n s.phase=1\n local minX,maxX,minZ,maxZ=math.huge,-math.huge,math.huge,-math.huge\n for _,p in ipairs(puffs) do local q=p.entity.pos;minX=math.min(minX,q.x);maxX=math.max(maxX,q.x);minZ=math.min(minZ,q.z);maxZ=math.max(maxZ,q.z) end\n if math.abs(maxX-minX-25)>=1 or math.abs(maxZ-minZ-17)>=1 then s.phase=0 end\nelseif #puffs==4 then s.phase=2 end\ns.geometryReady=#puffs>0\nif #puffs==0 then s.phase=0 end\nif s.goal and not s.goalBait and GUI:GetTime()<s.goalUntil then\n if not s.safe(s.goal,s.hazards((boss.castinginfo.channelingid==30567 or boss.castinginfo.channelingid==30602))) then s.clear() end\nend\n\n",
