						actionLua = "local s=_G.JacobSilkieGuide\nlocal boss=TensorCore.mGetEntity(eventArgs.entityID)\nif not s or not boss or (Argus.getEntityModel(boss)~=14834 and Argus.getEntityModel(boss)~=14837) then self.used=true;return end\nif not s.pullStart then s.pullStart=GUI:GetTime() end\nlocal id=eventArgs.spellID\nif (id==30566 or id==30601) then\n s.stage=nil;s.side=nil;s.tethers={};s.sweepUntil=nil;s.sweepGoal=nil;s.plan1Announced=nil;s.rowMid=nil;s.laneSide=nil;s.clear()\n s.phase=0\nelseif (id==30543 or id==30578) and s.phase==3 then\n s.tankSide=nil\nelseif (id==30543 or id==30578) and s.phase==1 then\n local hazards=s.hazards(true)\n local candidates={}\n for _,p in ipairs(s.puffs or {}) do\n  if p.kind==1512 then\n   for x=-3,3,.5 do for z=-3,3,.5 do candidates[#candidates+1]={x=p.entity.pos.x+x,y=p.entity.pos.y,z=p.entity.pos.z+z} end end\n  end\n end\n local player=TensorCore.mGetPlayer()\n if player and s.guide(s.pick(candidates,hazards,player.pos),9000,'Remaining green puff',hazards) then AnyoneCore.Shotcall('Go green',true,4,false) end\nelseif (id==30558 or id==30593) and s.phase==3 and s.laneSide then\n -- Target-selection event 31227 gives each player their precise place in the line.\n AnyoneCore.Shotcall('Stack',true,4,false)\nelseif (id==30567 or id==30602) and (s.phase==1 or s.phase==3 or s.phase==4) then\n if not s.geometryReady then s.clear();self.used=true;return end\n local hazards=s.hazards(true)\n local candidates={}\n local player=TensorCore.mGetPlayer()\n if not player then self.used=true;return end\n if s.phase==3 then\n  local active={}\n  for _,e in ipairs(s.entities(11370)) do\n   if (Argus.getEntityModel(e)==14835 or Argus.getEntityModel(e)==14838) and Argus.isEntityVisible(e) then\n    local _,_,kind=Argus.getEntityAuras(e)\n    if kind==1510 or kind==1511 or kind==1512 then active[#active+1]={entity=e,kind=kind} end\n   end\n  end\n  if #active==2 then\n   local lane=(active[1].entity.pos.x+active[2].entity.pos.x)/2\n   s.laneSide=lane<s.center.x and -1 or 1\n   s.rowMid=(active[1].entity.pos.z+active[2].entity.pos.z)/2\n   -- The hose fronts have passed the puff rows by this cast. Blue crosses can\n   -- require stepping sideways out of the original unwashed column.\n   for dx=-19,19,.5 do for dz=-19,19,.5 do\n    candidates[#candidates+1]={x=s.center.x+dx,y=boss.pos.y,z=s.center.z+dz}\n   end end\n  elseif #active>=6 then\n   for x=-4,4,.5 do for z=-4,4,.5 do candidates[#candidates+1]={x=boss.pos.x+x,y=boss.pos.y,z=boss.pos.z+z} end end\n  end\n elseif s.phase==1 then\n  for _,p in ipairs(s.puffs) do\n   if p.kind==1512 then\n    for x=-4,4,.5 do for z=-4,4,.5 do candidates[#candidates+1]={x=p.entity.pos.x+x,y=boss.pos.y,z=p.entity.pos.z+z} end end\n   end\n  end\n else\n  -- Uptime finishes in the small safe area north of Silkie, inside the donut.\n  if s.mode==1 then\n   for z=-3.5,-1,.25 do for x=-1.5,1.5,.25 do candidates[#candidates+1]={x=boss.pos.x+x,y=boss.pos.y,z=boss.pos.z+z} end end\n  else\n   for x=-4,4,.5 do for z=-4,4,.5 do candidates[#candidates+1]={x=boss.pos.x+x,y=boss.pos.y,z=boss.pos.z+z} end end\n  end\n end\n local _,tail=Argus.getEntityAuras(boss)\n if tail==1502 then hazards[#hazards+1]={kind='donut',x=boss.pos.x,z=boss.pos.z,h=0}\n elseif tail==1501 then hazards[#hazards+1]={kind='cross',x=boss.pos.x,z=boss.pos.z,h=boss.pos.h} end\n local reference=player.pos\n if s.phase==4 and s.mode==1 then reference={x=boss.pos.x,y=boss.pos.y,z=boss.pos.z-3.5} end\n local goal=s.pick(candidates,hazards,reference)\n s.lastSpreeGuide={phase=s.phase,time=GUI:GetTime(),candidateCount=#candidates,hazardCount=#hazards,goal=goal}\n s.guide(goal,(eventArgs.channelTimeMax+.3)*1000,s.phase==4 and s.mode==1 and 'Max north' or 'Safe spot',hazards)\nelseif ((id==30545 or id==30580) or (id==30546 or id==30581)) and s.phase==4 then\n if s.mode==1 then\n  local x,y,z,active=Argus.getWaymarkInfo(1)\n  if active then\n   s.p4Bait={x=x,y=boss.pos.y,z=math.max(s.center.z-19,z-.25)}\n   s.p4Origins={}\n   for _,p in ipairs(s.puffs or {}) do s.p4Origins[p.entity.id]={x=p.entity.pos.x,z=p.entity.pos.z} end\n   s.guide(s.p4Bait,10000,'Bait behind A',{},true)\n   AnyoneCore.Shotcall('Bait behind A',true,4,false)\n  else s.clear() end\n end\nend\nself.used=true\n",
