						aType = "Lua",
						actionLua = "local s=_G.JacobSilkieGuide\nlocal helper=TensorCore.mGetEntity(eventArgs.entityID)\nif not s or not helper or not s.boss then self.used=true;return end\nlocal boss=s.boss\nlocal hazards=s.hazards(false)\nhazards[#hazards+1]={kind='cone',x=helper.pos.x,z=helper.pos.z,h=helper.pos.h,angle=math.pi*1.25}\nlocal choices={}\nif s.phase==4 and s.mode==1 then\n -- A five-yalm tile corner, on the safe flank, common to all four players.\n if s.p4Bait then\n  local safeSide=math.sin(helper.pos.h)>0 and -1 or 1\n  -- Small lateral step in the pocket behind the north-positioned boss.\n  local point\n  if safeSide==1 then\n   point={x=-328.17,y=471,z=-165.17}\n  else\n   point={x=-342.06,y=471,z=-165.67}\n  end\n  if math.abs(point.x-s.center.x)<=19 and math.abs(point.z-s.center.z)<=19 then choices[#choices+1]=point end\n end\nelse\n for _,side in ipairs({-1,1}) do\n  choices[#choices+1]={x=boss.pos.x+side*math.cos(boss.pos.h)*5,y=boss.pos.y,z=boss.pos.z-side*math.sin(boss.pos.h)*5}\n end\nend\nif s.phase==4 and s.mode==1 then s.p4AcrossSide=math.sin(helper.pos.h)>0 and -1 or 1 end\nlocal chosen=s.pick(choices,hazards,boss.pos)\nif not chosen then s.lastP4Blocked={time=GUI:GetTime(),phase=s.phase,reason='Bait intersects last swipe',bait=s.p4Bait,helper={x=helper.pos.x,z=helper.pos.z,h=helper.pos.h}};s.clear();self.used=true;return end\ns.side=chosen.x>=boss.pos.x and 1 or -1\ns.sweepGoal=chosen\nif s.phase==4 and s.mode==1 then s.p4AcrossPoint=chosen end\ns.sweepUntil=GUI:GetTime()+eventArgs.channelTimeMax\nif s.phase==4 and s.mode==0 then\n local puff=TensorCore.mGetEntity(s.tethers[TensorCore.mGetPlayer().id] or 0)\n if puff then\n  -- The puff jumps ten yalms; stand just to its safe side, not at its landing spot.\n  s.guide({x=puff.pos.x+s.side*1.5,y=puff.pos.y,z=puff.pos.z},eventArgs.channelTimeMax*1000,'Send puff sideways',{},true)\n end\nelse\n s.guide(chosen,(eventArgs.channelTimeMax+(s.phase==4 and s.mode==1 and 3 or 0))*1000,s.phase==4 and s.mode==1 and 'Safe side' or 'Safe flank',hazards)\nend\nlocal direction=s.side==1 and 'Right' or 'Left'\nif s.phase==4 and s.mode==1 then AnyoneCore.Shotcall(s.p4AcrossSide==-1 and 'Left' or 'Right',true,4,false) else AnyoneCore.Shotcall(s.phase==1 and (direction..', stack') or direction,true,4,false) end\nself.used=true\n",
