3+1]\n   local e=TensorCore.mGetEntity(v.entityID)\n   local remaining=e and e.castinginfo.casttime-e.castinginfo.channeltime or 0\n   -- Follow-up donut is relevant after the initial circle clears.\n   if n<3 then radius=math.max(radius,inner+.8)\n   elseif remaining<=2.2 then radius=math.min(radius,inner-.8) end\n  end\n end\n goal={x=-35+dx/length*radius,y=p.pos.y,z=-271+dz/length*radius}\n if math.abs(goal.x+35)>19 or math.abs(goal.z+271)>19 then goal=nil end\n\nelse\n local e=w.stack\n green:addTimedCircleOnEnt(ms,e.id,5,0,false,true)\n AnyoneCore.addTimedWorldTextOnEnt(ms,'Stack',e.id,0xFF99FF99,true,.9,2)\n if w.blue then AnyoneCore.addTimedWorldTextOnEnt(ms,'Blue',w.blue.id,0xFFFFCC77,true,.9,2) end\n AnyoneCore.addWorldTextCountdown(ms,setmetatable({entityID=e.id},{__index=function(t,k) local e=TensorCore.mGetEntity(t.entityID);if not e then return 0 end;if k=='x' then return e.pos.x elseif k=='y' then return e.pos.y+1 elseif k=='z' then return e.pos.z end end}),0xFFFFFFFF,true,1)\n if w.state.blueID~=p.id and e.id~=p.id then goal=e.pos end\nend\nif goal then\n for _,v in ipairs(Argus.getCurrentAOEs()) do\n  local id=v.aoeID;local n\n  if id>=30301 and id<=30306 then n=id-30301 elseif id>=30623 and id<=30628 then n=id-30623 end\n  if n then\n   local radius=({8,13,18})[n%3+1]\n   local distance=math.sqrt((goal.x-v.x)^2+(goal.z-v.z)^2)\n   local e=TensorCore.mGetEntity(v.entityID)\n   local remaining=e and e.castinginfo.casttime-e.castinginfo.channeltime or 0\n   if n<3 and distance<radius+.6 or n>=3 and remaining<=2.2 and distance>radius-.6 then goal=nil;break end\n  end\n end\nend\nif goal then\n if w.mode=='stack' then w.state.guidePending=false end\n local d=TensorCore.getDistance2d(p.pos,goal)\n local shape=green:addTimedCircle(guideMs,goal.x,goal.y+.05,goal.z,.5,0,false,true)\n if shape then _G.JacobGladiatorCurseGuideDraws[#_G.JacobGladiatorCurseGuideDraws+1]=shape end\n if d>1 then\n  shape=green:addTimedArrow(guideMs,p.pos.x,p.pos.y+.05,p.pos.z,TensorCore.getHeadingToTarget(p.pos,goal),math.max(.1,d-1),.8,1,1.4,0,false)\n  if shape then _G.JacobGladiatorCurseGuideDraws[#_G.JacobGladiatorCurseGuideDraws+1]=shape end\n end\nend\nif not w.guideOnly then AnyoneCore.Shotcall(w.message,true,5,false) end\nself.used=true",
