et(p.pos,q),math.max(.1,dist-1),.7,1,1.3,0,false)\n  if shape then w.state.draws[#w.state.draws+1]=shape end\n end\nend\nif first then AnyoneCore.Shotcall((w.gold>0 or w.silver>0) and 'Go to correct square' or 'Dodge lasers',true,4,false) end\nself.used=true",
