oe;keys[#keys+1]=tostring(v.aoe.entityID) end\n end\n table.sort(keys);phase='lanes:'..table.concat(keys,',');deadline=firstRack\nelse\n -- Stronger fill for the busy final five seconds; no per-frame timed redraws.\n if state.gold>0 or state.silver>0 or state.laserEnd-now<=5.5 then phase='cells-bright' end\nend\nstate.finish=math.max(state.finish,finalEnd)\nif state.shown==phase then return false end\n_G.JacobGladiatorCells={beams=state.beams,gold=state.gold,silver=state.silver,deadline=deadline,player=p,state=state,phase=phase,racks=active,afterLaser=afterLaser,bright=phase~='cells'}\nreturn true",
