						actionLua = "local w=_G.JacobGladiatorTowerPlan\nif not w then self.used=true;return end\nif w.preCall then\n if not w.state.precalled then AnyoneCore.Shotcall(w.spread and 'Spread soon' or 'Soak tower soon',true,2,false);w.state.precalled=true end\n self.used=true;return\nend\nif w.state.shown==w.wave then self.used=true;return end\nw.state.shown=w.wave\nfor _,id in ipairs(w.state.draws) do Argus.deleteTimedShape(id) end\nw.state.draws={}\nlocal p=w.player\nif w.spread then w.ms=math.max(1,w.ms-800) end\nif w.spread then\n AnyoneCore.addTimedWorldTextOnEnt(w.ms,'Spread',p.id,0xFF9999FF,true,.9,2)\n local shape=TensorCore.getStaticDrawer(0x503333FF,2):addTimedCircleOnEnt(w.ms,p.id,15,0,false,true)\n if shape then w.state.draws[#w.state.draws+1]=shape end\n AnyoneCore.addWorldTextCountdown(w.ms,setmetatable({entityID=p.id},{__index=function(t,k) local e=TensorCore.mGetEntity(t.entityID);if not e then return 0 end;if k=='x' then return e.pos.x elseif k=='y' then return e.pos.y+1 elseif k=='z' then return e.pos.z end end}),0xFFFFFFFF,true,1)\n local q=w.spreadGoal\n if q then\n  local dist=TensorCore.getDistance2d(p.pos,q)\n  if dist>1 then local arrow=TensorCore.getStaticDrawer(0xFF66FF99,2):addTimedArrow(w.ms,p.pos.x,p.pos.y+.05,p.pos.z,TensorCore.getHeadingToTarget(p.pos,q),math.max(.1,dist-1),.8,1,1.4,0,false);if arrow then w.state.draws[#w.state.draws+1]=arrow end end\n end\n AnyoneCore.Shotcall('Spread now, avoid towers',true,4,false)\nelse\n local q=w.goal;local d=TensorCore.getStaticDrawer(0x5033FF66,2)\n local assignment=_G.JacobGladiatorMonumentAssignment\n if assignment then\n  for id,record in pairs(assignment.records) do\n   if record.order~=w.wave then\n    local marker=d:addTimedCircleOnEnt(w.ms,id,.8,0,false,true)\n    if marker then w.state.draws[#w.state.draws+1]=marker end\n   end\n  end\n end\n local shape=d:addTimedCircle(w.ms,q.x,q.y+.05,q.z,3,0,false,true)\n if shape then w.state.draws[#w.state.draws+1]=shape end\n local dist=TensorCore.getDistance2d(p.pos,q)\n if dist>1 then local arrow=d:addTimedArrow(w.ms,p.pos.x,p.pos.y+.05,p.pos.z,TensorCore.getHeadingToTarget(p.pos,q),math.max(.1,dist-1),.8,1,1.4,0,false);if arrow then w.state.draws[#w.state.draws+1]=arrow end end\n AnyoneCore.addWorldTextCountdown(w.ms,{x=q.x,y=q.y+1,z=q.z},0xFFFFFFFF,true,1)\n AnyoneCore.Shotcall('Soak tower now',true,4,false)\nend\nself.used=true",
