					{
						category = "Lua",
						conditionLua = "local p=TensorCore.mGetPlayer()\nif not p or not p.incombat then _G.JacobGladiatorTowerState=nil;return false end\nlocal first=TensorCore.getBuff(p,3004);local second=TensorCore.getBuff(p,3005)\nif not first and not second then return false end\nlocal now=GUI:GetTime();local towers={};local earliest=math.huge;local latest=0\nlocal assignment=_G.JacobGladiatorMonumentAssignment\nif not assignment or now<assignment.time or now-assignment.time>60 then\n local tank,healer,melee,ranged\n local records={}\n for _,e in pairs(TensorCore.getEntityGroupList('Party') or {}) do\n  local one=TensorCore.getBuff(e,3004);local two=TensorCore.getBuff(e,3005)\n  if one or two then\n   local v={entity=e,order=one and 1 or 2};records[e.id]=v\n   local j=e.job\n   if j==19 or j==21 or j==32 or j==37 then tank=v\n   elseif j==24 or j==28 or j==33 or j==40 then healer=v\n   elseif j==20 or j==22 or j==30 or j==34 or j==39 or j==41 then melee=v\n   else ranged=v end\n  end\n end\n if not tank or not healer or not melee or not ranged then return false end\n local monument=_G.JacobGladiatorMonumentState\n if not monument or not monument.last or #monument.last~=2 then return false end\n local n=monument.last[1];local south=monument.last[2]\n if n.z>south.z then n,south=south,n end\n -- Cardinal final corners need deterministic quadrant tie-breaking for E/W towers.\n n={x=math.abs(n.x+35)<1 and -25 or n.x,z=n.z}\n south={x=math.abs(south.x+35)<1 and -45 or south.x,z=south.z}\n tank.anchor=n;healer.anchor=south\n melee.anchor=melee.order==tank.order and south or n\n ranged.anchor=ranged.order==healer.order and n or south\n assignment={records=records,time=now};_G.JacobGladiatorMonumentAssignment=assignment\nend\nlocal mine=assignment.records[p.id]\nif not mine then return false end\nfor _,a in ipairs(Argus.getCurrentAOEs()) do\n if a.aoeID==30314 or a.aoeID==30636 then\n  local e=TensorCore.mGetEntity(a.entityID)\n  if e and e.castinginfo.channelingid==a.aoeID then\n   local deadline=now+e.castinginfo.casttime-e.castinginfo.channeltime+.3\n   towers[#towers+1]={entity=e,x=a.x,y=a.y,z=a.z,deadline=deadline}\n   earliest=math.min(earliest,deadline);latest=math.max(latest,deadline)\n  end\n end\nend\nif #towers<2 then return false end\nlocal w=_G.JacobGladiatorTowerState\nif not w or now>w.finish+1 or now<w.started then\n if #towers<4 then return false end\n w={started=now,first=earliest,finish=latest,draws={}};_G.JacobGladiatorTowerState=w\nend\nlocal wave=now>w.first+.2 and 2 or 1\nif w.shown==wave then\n if wave==1 and not w.precalled and now>=w.first-1 and now<w.first then\n  _G.JacobGladiatorTowerPlan={state=w,preCall=true,spread=mine.order==2};return true\n end\n return false\nend\nlocal spread=wave==mine.order\nlocal active={}\nfor _,t in ipairs(towers) do if t.deadline<=earliest+.4 then active[#active+1]=t end end\nif #active~=2 then return false end\nlocal goal=active[1];local best=math.huge\nfor _,t in ipairs(active) do\n local dist=(t.x-mine.anchor.x)^2+(t.z-mine.anchor.z)^2\n if dist<best then goal=t;best=dist end\nend\nlocal spreadGoal\nif spread then\n local choices={{x=-35,z=-289},{x=-17,z=-271},{x=-35,z=-253},{x=-53,z=-271}}\n best=math.huge\n for _,q in ipairs(choices) do\n  local clear=true\n  for _,t in ipairs(active) do if (q.x-t.x)^2+(q.z-t.z)^2<18^2 then clear=false end end\n  if clear then\n   local distance=(q.x-mine.anchor.x)^2+(q.z-mine.anchor.z)^2\n   if distance<best then best=distance;spreadGoal={x=q.x,y=p.pos.y,z=q.z} end\n  end\n end\nend\n_G.JacobGladiatorTowerPlan={state=w,wave=wave,spread=spread,goal=goal,spreadGoal=spreadGoal,player=p,ms=math.max(1,(earliest-now)*1000)}\nreturn true",
