						actionLua = "local p=TensorCore.mGetPlayer()\nlocal target=TensorCore.mGetEntity(eventArgs.targetID)\nif not p or not target then self.used=true;return end\nlocal boss\nfor _,e in pairs(TensorCore.getEntityGroupList('ContentID',{contentid=11387}) or {}) do\n if e.incombat and Argus.getEntityModel(e)~=9020 then boss=e;break end\nend\nif not boss then self.used=true;return end\nlocal d=TensorCore.getStaticDrawer(0x5033FF66,2)\nd:addTimedRectOnEnt(5500,boss.id,60,8,target.id,0,true,false,true,0,false)\nd:addTimedCircleOnEnt(5500,target.id,.8,0,false,true)\nAnyoneCore.addTimedWorldTextOnEnt(5500,'Stack',target.id,0xFF99FF99,true,.9,2)\nAnyoneCore.addWorldTextCountdown(5500,setmetatable({entityID=target.id},{__index=function(t,k) local e=TensorCore.mGetEntity(t.entityID);if not e then return 0 end;if k=='x' then return e.pos.x elseif k=='y' then return e.pos.y+1 elseif k=='z' then return e.pos.z end end}),0xFFFFFFFF,true,1)\nlocal tank=p.job==19 or p.job==21 or p.job==32 or p.job==37\nlocal dist=TensorCore.getDistance2d(boss.pos,target.pos)\nif dist>1 then\n local ratio=(tank and 2 or math.max(3,dist-2))/dist\n local goal={x=boss.pos.x+(target.pos.x-boss.pos.x)*ratio,y=p.pos.y,z=boss.pos.z+(target.pos.z-boss.pos.z)*ratio}\n local length=TensorCore.getDistance2d(p.pos,goal)\n if p.id~=target.id and length>1 then d:addTimedArrow(5500,p.pos.x,p.pos.y+.05,p.pos.z,TensorCore.getHeadingToTarget(p.pos,goal),math.max(.1,length-1),.8,1,1.4,0,false) end\nend\nif tank then AnyoneCore.Shotcall('Tank in front',true,4,false)\nelseif p.id==target.id then AnyoneCore.Shotcall('Line stack on you',true,4,false) end\nself.used=true",
