				{
					data = 
					{
						category = "Lua",
						conditionLua = "local p=TensorCore.mGetPlayer()\nlocal state=_G.JacobGladiatorRushGuide\nif not p or not p.incombat then\n if state then _G.JacobGladiatorRushGuidePlan={clear=true,state=state};return true end\n _G.JacobGladiatorResolvedAOEs=nil;return false\nend\nlocal front,back,lanes={},{},{}\nlocal resolved=_G.JacobGladiatorResolvedAOEs or {}\nlocal now=GUI:GetTime()\nfor _,a in ipairs(Argus.getCurrentAOEs()) do\n local id=a.aoeID\n local e=TensorCore.mGetEntity(a.entityID)\n local hit=resolved[tostring(a.entityID)..':'..id]\n if e and e.castinginfo.channelingid==id and (type(hit)~='number' or now-hit>3) then\n  if id==30299 or id==30621 then front[#front+1]=a\n  elseif id==30300 or id==30622 then back[#back+1]=a\n  elseif id>=30296 and id<=30298 or id>=30618 and id<=30620 then lanes[#lanes+1]=a end\n end\nend\nlocal aoes,step\nif #front==2 then aoes=front;step='first'\nelseif #front==0 and #back==2 then aoes=back;step='second'\nelse\n if #front==0 and #back==0 and state then _G.JacobGladiatorRushGuidePlan={clear=true,state=state};return true end\n return false\nend\nlocal keys={}\nlocal deadline=math.huge\nfor _,a in ipairs(aoes) do\n keys[#keys+1]=string.format('%s:%.1f:%.1f:%.2f',a.entityID,a.x,a.z,a.heading)\n local e=TensorCore.mGetEntity(a.entityID)\n if not e or e.castinginfo.channelingid~=a.aoeID then return false end\n deadline=math.min(deadline,now+e.castinginfo.casttime-e.castinginfo.channeltime+.3)\nend\ntable.sort(keys)\nlocal key=step..':'..table.concat(keys,',')\nif state and step=='first' and state.callStep=='second' then\n for _,id in ipairs(state.draws) do Argus.deleteTimedShape(id) end\n state={draws={}};_G.JacobGladiatorRushGuide=state\nend\nif not state then state={draws={}};_G.JacobGladiatorRushGuide=state end\nif state.key==key then return false end\nif state.pending~=key then state.pending=key;state.ready=now+.5;return false end\nif now<state.ready or deadline<=now then return false end\nlocal best,score=nil,math.huge\nfor x=-53,-17,.5 do for z=-289,-253,.5 do\n local safe=true\n for _,a in ipairs(aoes) do\n  local forward=(x-a.x)*math.sin(a.heading)+(z-a.z)*math.cos(a.heading)\n  if forward> -1.5 then safe=false;break end\n end\n\n if safe then\n  -- Use the predicted AoE half-planes, never the mirage actor positions.\n  -- Start close to BOTH cleave edges so crossing their junction is a short move.\n  local value\n  if step=='first' then\n   value=0\n   for _,a in ipairs(aoes) do\n    local forward=(x-a.x)*math.sin(a.heading)+(z-a.z)*math.cos(a.heading)\n    value=value+(forward+1.5)^2\n   end\n   value=value+.001*((x-p.pos.x)^2+(z-p.pos.z)^2)\n  else\n   value=(x-p.pos.x)^2+(z-p.pos.z)^2\n  end\n  if value<score then score=value;best={x=x,y=p.pos.y,z=z} end\n end\nend end\nif not best then return false end\n_G.JacobGladiatorRushGuidePlan={state=state,key=key,point=best,ms=math.max(1,(deadline-now)*1000),step=step,player=p}\nreturn true",
