						actionLua = "local player = TensorCore.mGetPlayer()\nif not player or player.localmapid ~= 1075 then\n    self.used = true\n    return\nend\n\nlocal vfx = tonumber(vfxID)\nif vfx ~= 24 and vfx ~= 61 and vfx ~= 120 then\n    self.used = true\n    return\nend\n\nlocal brand = TensorCore.mGetEntity(primaryEntityID)\nlocal target = TensorCore.mGetEntity(secondaryEntityID)\nif not brand or not target or not brand.pos or not target.pos then\n    self.used = true\n    return\nend\n\nlocal function flameNumber(entity)\n    if not entity then\n        return nil\n    end\n    if TensorCore.getBuff(entity, 3272) then return 1 end\n    if TensorCore.getBuff(entity, 3273) then return 2 end\n    if TensorCore.getBuff(entity, 3274) then return 3 end\n    if TensorCore.getBuff(entity, 3275) then return 4 end\n    return nil\nend\n\nlocal targetNumber = flameNumber(target)\nlocal nextNumber = 99\nlocal party = TensorCore.getEntityGroupList(\"Party\") or {}\nlocal seen = {}\nlocal function considerPartyMember(entityID)\n    if not entityID or entityID == 0 or entityID == -1 or seen[entityID] then\n        return\n    end\n    seen[entityID] = true\n    local number = flameNumber(TensorCore.mGetEntity(entityID))\n    if number and number < nextNumber then\n        nextNumber = number\n    end\nend\nfor _, member in pairs(party) do\n    if member then\n        considerPartyMember(member.id)\n    end\nend\nconsiderPartyMember(player.id)\nlocal targetID = tonumber(secondaryEntityID)\nlocal playerID = tonumber(player.id)\nlocal isMine = targetID and playerID and targetID == playerID\nlocal isMyTurn = isMine and targetNumber and targetNumber == nextNumber\nlocal overlay = Argus2.RenderFlags.FLAG_RENDER_OVERLAY\n\nlocal drawer\nif isMyTurn then\n    drawer = TensorCore.getCachedDrawer(0xFF40FF40, 0xFF40FF40, 0xFF20AA20, 0xFFFFFFFF, 3)\nelseif isMine then\n    drawer = TensorCore.getCachedDrawer(0xFF80C0FF, 0xFF80C0FF, 0xFF4060AA, 0xFFFFFFFF, 2)\nelse\n    drawer = TensorCore.getCachedDrawer(0xFF707070, 0xFF707070, 0xFF404040, 0xFFFFFFFF, 1)\nend\n\ndrawer:addTimedLine(\n    10000,\n    brand.pos.x,\n    brand.pos.y + 0.15,\n    brand.pos.z,\n    target.pos.x,\n    target.pos.y + 0.15,\n    target.pos.z,\n    isMyTurn and 0.35 or 0.16,\n    isMyTurn and 0.8 or 0.35,\n    0\n)\n\nself.used = true",
