						conditionLua = "local s=data.zeless_cut5;local p=TensorCore.mGetPlayer()\nif data.zeless_cut_mode~=5 or not s or not p or not p.incombat then return false end\nlocal now=TensorReactions_CurrentCombatTimer\nif now<s.started or now-s.started>90 then data.zeless_cut5=nil;return false end\nlocal n\nfor id=3268,3275 do if TensorCore.getBuff(p,id) then n=id<=3271 and id-3267 or id-3271;break end end\nif n then s.number=n end\nn=s.number\nif not n then return false end\nfor _,e in pairs(TensorCore.entityList('contentid=11394')) do\n local b=TensorCore.getBuff(e,2397)\n if b and b.stacks>=450 and b.stacks<=457 then\n  if not s.lasers[e.id] then s.lasers[e.id]={number=(b.stacks-450)%4+1,blue=b.stacks>=454,x=e.pos.x,z=e.pos.z} end\n end\nend\nlocal k=s.cuts;local wave=s.waves\nif k>=8 then return false end\nlocal color\nif s.firstBlue~=nil then\n local blue=k<4 and s.firstBlue or k>=4 and not s.firstBlue\n color=blue and 'blue ' or 'red '\nend\nlocal vuln=TensorCore.getBuff(p,2941)\nlocal safe=not vuln or vuln.duration<=0\nlocal recovered=wave>0 and s.baited[wave]~=nil and now>=s.baited[wave]\nlocal key;local text\nif k==4 and not s.called['bait2'] then key='bait2';text=(n==1 or n==2) and 'Bait ward 2, then puddles' or 'Bait puddles'\nelseif k==6 and (n==3 or n==4) and not s.called['bait3'] then key='bait3';text='Bait ward 3'\nelseif safe then\n local cut=false\n if n==1 then cut=(k==0 and TensorCore.getBuff(p,3272)~=nil) or (k==4 and wave>=2 and recovered)\n elseif n==2 then cut=k==1 or k==6\n elseif n==3 then cut=(k==2 and wave==1 and recovered) or (k==5 and wave>=3 and recovered)\n elseif n==4 then cut=k==3 or k==7 end\n if cut then key='cut:'..k;text='Cut '..(color or '')..n..' now'\n elseif n==4 and recovered and ((wave==1 and k>=1 and k<3) or (wave>=3 and k>=5 and k<7)) then key='move:'..wave;text='Move for '..(color or '')..'4' end\nend\nif not key or s.called[key] then return false end\ndata.zeless_cut5_plan={state=s,key=key,text=text}\nreturn true",
