						conditionLua = "local p=TensorCore.mGetPlayer()\nif data.zeless_cut_mode~=2 or not p or not p.incombat then return false end\nlocal now=TensorReactions_CurrentCombatTimer\nlocal s=data.zeless_mirror_moves\nif not s or now<s.started or now-s.started>75 then\n s={started=now,lasers={},done={},stageShapes={},groups={}};data.zeless_mirror_moves=s\n function s.unsafe(x,z,fonts)\n  for _,q in ipairs(fonts) do\n   local dx,dz=x-q.x,z-q.z\n   local f=dx*math.sin(q.h)+dz*math.cos(q.h)\n   local side=dx*math.cos(q.h)-dz*math.sin(q.h)\n   if f>=-100 and f<=100 and math.abs(side)<5.75 then return true end\n  end\n  return false\n end\n function s.clearPath(px,pz,x,z,lasers)\n  for _,q in ipairs(lasers) do\n   local c,si=math.cos(q.h),math.sin(q.h)\n   local r0=(px-q.x)*c-(pz-q.z)*si\n   local r1=(x-q.x)*c-(z-q.z)*si\n   if math.abs(r1)<.6 or r0*r1<0 then return false end\n  end\n  return true\n end\nend\nfor _,e in pairs(TensorCore.entityList('contentid=11394')) do\n local b=TensorCore.getBuff(e,2397)\n if b and b.stacks>=450 and b.stacks<=457 and not s.lasers[e.id] then s.lasers[e.id]=b.stacks end\nend\nlocal total,redGone,blueGone=0,0,0\nlocal remaining={}\nfor id,stack in pairs(s.lasers) do\n total=total+1\n local e=TensorCore.mGetEntity(id);local b=e and TensorCore.getBuff(e,2397)\n if b and b.stacks==stack then remaining[#remaining+1]={x=e.pos.x,z=e.pos.z,h=e.pos.h}\n elseif stack<=453 then redGone=redGone+1 else blueGone=blueGone+1 end\nend\nif total~=8 then return false end\nlocal stage\nif redGone==4 and blueGone==4 then stage=2 elseif redGone==4 or blueGone==4 then stage=1 end\nif not stage or s.done[stage] then return false end\nlocal mirrors=data.zeless_mirrors\nif not mirrors or mirrors.clock~='combat' then return false end\nif not s.firstDeadline then for _,q in pairs(mirrors.fonts) do s.firstDeadline=math.min(s.firstDeadline or math.huge,q.deadline) end end\nif not s.firstDeadline then return false end\nlocal fonts={};local deadline=math.huge;local sources={}\nfor id,q in pairs(mirrors.fonts) do\n local first=q.deadline<=s.firstDeadline+.6\n if (stage==1 and first or stage==2 and not first) and q.deadline>now then\n  fonts[#fonts+1]=q;sources[id]=true;deadline=math.min(deadline,q.deadline)\n end\nend\nif #fonts==0 then return false end\nif stage==1 and not s.unsafe(p.pos.x,p.pos.z,fonts) then s.done[stage]=true;return false end\n-- Keep the route within the arena, off remaining lines, and outside the full-width mirror beams.\nlocal best=math.huge;local goal\nfor x=275,303,1 do for z=-124,-86,1 do\n local distance=(x-p.pos.x)^2+(z-p.pos.z)^2\n if distance<best and not s.unsafe(x,z,fonts) and s.clearPath(p.pos.x,p.pos.z,x,z,remaining) then\n  best=distance;goal={x=x,y=p.pos.y,z=z}\n end\nend end\nif not goal then return false end\ndata.zeless_mirror_move_plan={state=s,stage=stage,player=p,goal=goal,sources=sources,ms=math.max(1,math.min(10000,(deadline-now)*1000))}\nreturn true",
