						actionLua = "local now=TensorReactions_CurrentCombatTimer\nlocal targets={}\nfor _,e in pairs(TensorCore.getEntityGroupList('Party') or {}) do\n local b=TensorCore.getBuff(e,2941)\n if e.hp.current>0 and b and b.duration>0 then targets[#targets+1]={id=e.id,remaining=b.duration} end\nend\nif #targets~=2 then return end\n-- The first jump's vulnerability was applied first and has less time remaining.\ntable.sort(targets,function(a,b) return a.remaining<b.remaining end)\nlocal old=data.zeless_beacon_lines\nif old then for _,q in pairs(old.lines) do if q.shape then Argus.deleteTimedShape(q.shape) end end end\ndata.zeless_beacon_lines={bossID=eventArgs.entityID,finish=now+eventArgs.channelTimeMax+4,index=1,targets={targets[1].id,targets[2].id},lines={}}\nself.used=true",
