					{
						aType = "Lua",
						actionLua = "local s=data.zeless_beacon_lines\nlocal p=TensorCore.mGetPlayer();local boss=TensorCore.mGetEntity(s.bossID)\nlocal now=TensorReactions_CurrentCombatTimer\nif not p or not p.incombat or not boss or now>=s.finish or s.index>2 then\n for _,line in pairs(s.lines) do if line.shape then Argus.deleteTimedShape(line.shape) end end\n data.zeless_beacon_lines=nil;self.used=true;return\nend\nlocal party=TensorCore.getEntityGroupList('Party') or {}\nlocal ms=math.max(1,(s.finish-now)*1000)\nfor i=s.index,2 do\n local target=TensorCore.mGetEntity(s.targets[i]);local old=s.lines[i]\n if target and target.hp.current>0 and TensorCore.getBuff(target,2941) then\n  local dx,dz=target.pos.x-boss.pos.x,target.pos.z-boss.pos.z\n  local distance=math.sqrt(dx*dx+dz*dz);local covered=false\n  if distance>.1 then\n   local ux,uz=dx/distance,dz/distance\n   for _,other in pairs(party) do\n    if other.id~=target.id and other.hp.current>0 and not TensorCore.getBuff(other,2941) then\n     local ox,oz=other.pos.x-boss.pos.x,other.pos.z-boss.pos.z\n     local ahead=ox*ux+oz*uz;local side=ox*uz-oz*ux\n     if ahead>0 and ahead<distance and math.abs(side)<=4 then covered=true;break end\n    end\n   end\n  end\n  local d=TensorCore.getStaticDrawer(covered and 0x5033FF66 or 0x503333FF,2)\n  if not old then\n   local shape=d:addTimedRectOnEnt(ms,boss.id,65,8,target.id,0,true,false,true,0,false,Argus2.RenderFlags.FLAG_RENDER_OVERLAY)\n   s.lines[i]={shape=shape,covered=covered}\n  elseif old.covered~=covered then\n   if old.shape then d:updateTimedRectOnEnt(old.shape,ms,boss.id,65,8,target.id,0,true,false,true,0,false,Argus2.RenderFlags.FLAG_RENDER_OVERLAY) end\n   old.covered=covered\n  end\n elseif old and old.shape then\n  Argus.deleteTimedShape(old.shape);s.lines[i]=nil\n end\nend\nself.used=true",
